package main

import "fmt"

// Definisi Struct
type Server struct {
	Name   string
	Port   int
	Status string
}

// Value Receiver: Hanya membaca data, tidak bisa mengubah data asli
func (s Server) Info() string {
	return fmt.Sprintf("Server %s berjalan di port %d", s.Name, s.Port)
}

// Pointer Receiver (*): Bisa mengubah data asli dari struct tersebut
func (s *Server) Start() {
	s.Status = "Running"
	fmt.Println(s.Name, "telah dimulai.")
}

func main() {
	// Inisialisasi Struct
	webServer := Server{
		Name:   "Nginx-Proxy",
		Port:   8080,
		Status: "Stopped",
	}

	fmt.Println("Kondisi Awal:", webServer.Status)

	// Memanggil Value Receiver
	fmt.Println(webServer.Info())

	// Memanggil Pointer Receiver
	webServer.Start()

	// Status telah berubah!
	fmt.Println("Kondisi Akhir:", webServer.Status)
}
